import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void mergeArrays(List<Integer> array, int left, int middle, int right) {
        int sizeLeft = middle - left + 1;
        int sizeRight = right - middle;
        List<Integer> leftArr = new ArrayList<>(sizeLeft);
        List<Integer> rightArr = new ArrayList<>(sizeRight);
        for (int i = 0; i < sizeLeft; ++i) leftArr.add(array.get(left + i));
        for (int j = 0; j < sizeRight; ++j) rightArr.add(array.get(middle + 1 + j));
        int i = 0, j = 0, k = left;
        while (i < sizeLeft && j < sizeRight) {
            if (leftArr.get(i) <= rightArr.get(j)) {
                array.set(k++, leftArr.get(i++));
            } else {
                array.set(k++, rightArr.get(j++));
            }
        }
        while (i < sizeLeft) array.set(k++, leftArr.get(i++));
        while (j < sizeRight) array.set(k++, rightArr.get(j++));
    }

    public static void performMergeSort(List<Integer> array, int start, int end) {
        if (start < end) {
            int mid = start + (end - start) / 2;
            performMergeSort(array, start, mid);
            performMergeSort(array, mid + 1, end);
            mergeArrays(array, start, mid, end);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int size = scanner.nextInt();
        List<Integer> data = new ArrayList<>(size);
        for (int idx = 0; idx < size; ++idx) {
            data.add(scanner.nextInt());
        }
        performMergeSort(data, 0, size - 1);
        if (size == 1) {
            System.out.println(data.get(0));
        } else {
            int medianIndex = size / 2;
            System.out.println(data.get(medianIndex));
        }
        scanner.close();
    }
}
